        vm.assume(withdrawAmount <= type(uint256).max / 2);
        uint256 initialBal = address(c).balance;
        uint256 initialTotalSupply = 0; // sum of all balances at start is 0

        // Do a deposit from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        if (depositAmount >= 1 ether) {
            c.Deposit{value: depositAmount}();
        }

        // Now try cash-out
        vm.prank(caller);
        (bool success,) = address(c).call{gas: 100000}(abi.encodeWithSignature("CashOut(uint256)", withdrawAmount));

        // Compute total supply: sum of balances (we iterate over caller only as the only user) + contract balance
        // But we cannot iterate all addresses; instead we use the invariant: initialTotalSupply + deposits - withdrawals = final total supply
        // For simplicity, we check total contract balance vs initial
        uint256 finalBal = address(c).balance;
        // The invariant: if cashout succeeded, the contract balance decreased by withdrawAmount (if deposit had happened); but balance is public so we compare
        uint256 callerBalance = c.balances(caller);
        // General rule: total ether in system (contract balance + sum of all balances) is invariant
        // We approximate sum by just caller's balance, because other addresses are untouched
        assertTrue(callerBalance + finalBal == depositAmount - (success ? withdrawAmount : 0));
    }
}

