pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 cashOutAmount) public {
        // Bound depositAmount to at least 1 ether to pass MinDeposit
        vm.assume(depositAmount >= 1 ether);
        // Bound cashOut amount to be <= depositAmount so that CashOut may succeed or fail due to reentrancy, not insufficient balance
        vm.assume(cashOutAmount <= depositAmount);

        // Fund the caller and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before CashOut
        uint256 balanceBefore = c.balances(caller);

        // Attempt CashOut with reentrancy (the call may revert if external call fails)
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", cashOutAmount));

        // Rule: if the call reverted, the caller's balance must not have changed
        if (!success) {
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter == balanceBefore, "Balance changed after revert");
        }
    }
}

