import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 initialBalance, uint256 depositAmount, uint256 cashOutAmount) public {
        // Restrict inputs: caller must be non-zero, deposit >= MinDeposit, cashOut <= deposit
        vm.assume(caller != address(0));
        depositAmount = bound(depositAmount, 1 ether, 1000 ether);
        cashOutAmount = bound(cashOutAmount, 0, 1000 ether);
        vm.assume(initialBalance <= 1000 ether);

        // Set up initial conditions
        vm.deal(caller, initialBalance + depositAmount);
        vm.deal(address(this), initialBalance);

        // Get initial sum of balances (only deposit to caller's account if we deposit)
        uint256 sumBefore;
        // We can't iterate all addresses, so we use the property that sum of all balances equals address(this).balance
        // because the contract only holds Ether from deposits (no external transfers)
        uint256 contractBalanceBefore = address(c).balance;

        // Act: caller deposits and then cash out
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        vm.prank(caller);
        c.CashOut(cashOutAmount);

        // Get sum after
        uint256 contractBalanceAfter = address(c).balance;

        // The property: sum of balances should not decrease (it increases due to deposits or stays same if cash out is zero or fails)
        // Since we only deposit once and may cash out, the sum should be >= original (which was 0)
        // Actually, we need a property that holds for the reference but fails for the bug.
        // The reference has no overflow bug, so total Ether in contract reflects true deposits minus cashouts.
        // The bug causes overflow which destroys Ether, reducing contract balance.
        // So property: contract balance after calls >= contract balance before calls (since we only deposit positive amount)
        assertTrue(contractBalanceAfter >= contractBalanceBefore, "Contract balance must not decrease after deposit and cashout");
    }
}

