pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, address other, uint256 deposit1, uint256 deposit2) public {
        // Bound deposit amounts to reasonable values (0 to 100 ether)
        deposit1 = bound(deposit1, 0, 100 ether);
        deposit2 = bound(deposit2, 0, 100 ether);

        // Ensure caller and other are distinct and not zero address
        vm.assume(caller != address(0) && other != address(0) && caller != other);

        // Fund caller and other with enough ether
        vm.deal(caller, deposit1);
        vm.deal(other, deposit2);

        // Both deposit if amount >= MinDeposit (1 ether)
        vm.prank(caller);
        c.Deposit{value: deposit1}();
        vm.prank(other);
        c.Deposit{value: deposit2}();

        // caller withdraws some amount (0 to caller's balance)
        uint256 withdraw = bound(uint256(uint160(caller)) % (c.balances(caller) + 1), 0, c.balances(caller));
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", withdraw));
        if (!ok) {
            // If revert, no state change; property must hold
            vm.assume(false); // unreachable; we'll just check after
        }

        // After CashOut, sum of all balances must not exceed contract balance
        address[] memory users = new address[](2);
        users[0] = caller;
        users[1] = other;
        uint256 sumBalances;
        for (uint i = 0; i < users.length; i++) {
            sumBalances += c.balances(users[i]);
        }
        assertTrue(address(c).balance >= sumBalances);
    }
}

