pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, uint256 depositAmount, uint256 cashoutAmount) public {
        vm.assume(sender != address(0));
        // Bound deposit to avoid overflow; ensure it can be >= 1 ether
        vm.assume(depositAmount >= 1 ether);
        vm.assume(depositAmount <= type(uint256).max);
        vm.assume(cashoutAmount <= type(uint256).max);
        // Give sender enough ether
        vm.deal(sender, depositAmount);
        // Record balance before deposit
        uint256 balBefore = c.balances(sender);
        // Execute deposit
        vm.prank(sender);
        (bool depositOk,) = address(c).call{value: depositAmount}(abi.encodeWithSignature("Deposit()"));
        // If depositAmount > MinDeposit (1 ether), deposit should succeed
        // For the reference, depositAmount >= 1 ether succeeds
        if (depositAmount >= 1 ether) {
            assertTrue(depositOk, "Deposit should succeed when >= MinDeposit");
            // Balance increased by depositAmount
            assertTrue(c.balances(sender) == balBefore + depositAmount, "Balance should increase by deposit");
        }
        // Now cash out
        vm.prank(sender);
        (bool cashOutOk,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", cashoutAmount));
        // After CashOut, balance is non-negative and unchanged if it reverted
        // General rule: The final balance is always equal to the initial balance plus deposit minus cashout if cashout succeeded
        uint256 finalBal = c.balances(sender);
        if (cashOutOk) {
            assertTrue(finalBal == balBefore + depositAmount - cashoutAmount, "Final balance must match");
        } else {
            assertTrue(finalBal == balBefore + depositAmount, "Balance unchanged if CashOut reverted");
        }
    }
}

